  order_count=$(printf '%s' "$orders_json" | jq 'length')
  local date_str
  date_str=$(date '+%d/%m/%Y %H:%M')
  local app_url="${APP_URL:-}"

  # ── SKU grouping via jq ──────────────────────────────────────────
  local sku_rows_json
  sku_rows_json=$(printf '%s' "$orders_json" | jq '
    [ .[] | .order_id as $oid |
      (.products // []) | .[] |
      {
