        sku:      (.sku // (.storage_id // "N/A") // "N/A"),
        name:     (.name // "Unknown"),
        qty:      ((.quantity // 1) | tonumber)
      }
    ] |
    group_by(.sku) |
    map({
      sku:       (.[0].sku),
      name:      (.[0].name),
      total_qty: ([.[].qty] | add),
      orders:    ([.[].order_id] | unique | join(", "))
    }) |
    sort_by(.sku)
  ')

  # ── Build SKU table rows ─────────────────────────────────────────
  local sku_table_rows=""
  while IFS= read -r row; do
