      Printed: <strong>${dateStr}</strong>
    </div>
  </div>
  <div class="header-right">
    <div><span class="field-label">Picker:</span><span class="underline">&nbsp;</span></div>
    <div><span class="field-label">Started:</span><span class="underline">&nbsp;</span></div>
