</table>

<h2>Order Summary (${orderCount} orders)</h2>
<table>
  <thead>
    <tr>
      <th class="check">&#10003;</th>
      <th class="oid">Order #</th>
      <th>Customer</th>
      <th class="qty">Items</th>
    </tr>
